const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const n=value=>value===null||value===undefined||!Number.isFinite(Number(value))?'—':Number(value).toLocaleString('zh-CN',{maximumFractionDigits:1});
const bytes=value=>value===null||value===undefined?'—':value>=1024**3?n(value/1024**3)+' GiB':n(value/1024**2)+' MiB';
const at=value=>!value||!Number.isFinite(Date.parse(value))?'尚无记录':new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false});
const settingsFields=[
 ['sampleIntervalSeconds','自动采样周期','秒',30,600],['diskWarningPercent','磁盘预警','%',50,95],['diskCriticalPercent','磁盘严重告警','%',60,99],['minimumFreeGiB','最少可用磁盘','GiB',.25,100,.25],
 ['hostMemoryWarningPercent','主机内存预警','%',50,99],['processMemoryWarningMiB','本站进程内存预警','MiB',64,32768],['cpuLoadWarningPerCore','每核心负载预警','负载',.5,16,.1],
 ['jobQueueWarningCount','排队任务预警','条',1,10000],['jobStaleMinutes','任务多久未更新视为异常','分钟',1,240],['jobFailureWarningPercent','任务失败比例预警','%',1,100],['minimumJobSamples','计算失败比例所需完成样本','条',1,100],
 ['httpErrorWarningPercent','服务端 5xx 比例预警','%',1,100],['httpP95WarningMs','请求响应 P95 预警','毫秒',100,120000],['minimumRequestSamples','请求告警最少样本','次',1,1000],
 ['pendingPaymentWarningCount','待支付订单预警','笔',1,10000],['heldReservationMinutes','预占多久未结算视为异常','分钟',1,1440],['databaseWarningMiB','数据库容量预警','MiB',1,102400],['walWarningMiB','WAL 容量预警','MiB',1,10240],
 ['releasesWarningGiB','发布版本容量预警','GiB',.1,1000,.1],['backupsWarningGiB','备份目录容量预警','GiB',.1,1000,.1],['cacheWarningGiB','项目缓存容量预警','GiB',.1,100,.1],['artifactFailureWarningCount','生成文件补偿失败预警','项',1,10000]
];
const metricNames={disk:'磁盘占用','disk-free':'剩余磁盘',memory:'主机内存','process-memory':'本站进程内存','cpu-load':'主机负载',database:'数据库',wal:'数据库 WAL','directory-releases':'发布版本','directory-backups':'备份目录','directory-cache':'项目缓存','directory-summary-stale':'项目容量汇总超期',queue:'任务积压','stale-jobs':'任务超时未更新','job-failures':'任务失败比例','http-errors':'服务端错误','http-latency':'请求响应','held-reservations':'待结算预占','pending-payments':'待支付订单','expired-payments':'过期待支付订单',oss:'对象存储','artifact-failures':'生成文件存储补偿'};
export function monitoringSettingsPayload(form,version){
 const values={version,enabled:form.elements.enabled.checked};
 for(const [key]of settingsFields){const raw=form.elements[key]?.value.trim();if(!raw)throw Error('请填写所有监控阈值');const value=Number(raw);if(!Number.isFinite(value))throw Error('监控阈值必须为数字');values[key]=value;}
 return values;
}
export function monitoringPage(data){
 if(!data?.settings||!data.sampler)throw Error('监控数据格式不完整，请刷新后重试');
 const s=data.settings,l=data.latest,m=l?.metrics,a=l?.alerts||[],sampler=data.sampler;
 const card=(label,value,detail='',tone='')=>`<article class="monitor-card ${tone}"><span>${esc(label)}</span><strong>${esc(value)}</strong><p>${esc(detail)}</p></article>`;
 const status=!sampler.enabled?'自动采样已暂停':sampler.lastErrorAt?'采样发生异常':sampler.stale?'采样记录待更新':a.some(item=>item.severity==='critical')?'有严重告警':a.length?'有预警待处理':'当前未触发阈值';
 const line=(name,value)=>`<div><span>${esc(name)}</span><b>${esc(value)}</b></div>`;
 const directories=['releases','backups','cache'].map(key=>{const item=m?.directories?.[key],label={releases:'项目发布版本',backups:'项目备份目录',cache:'项目缓存'}[key];return line(label,item?(item.stale?'历史值 ':item.partial?'至少 ':'')+bytes(item.bytes):'未配置统计目录')+(item?`<p class="monitor-note">${esc(label)} · ${item.source==='root_summary'?'可信容量汇总':'有界目录扫描'} · ${esc(at(item.checkedAt))}${item.stale?' · 超过 26 小时，待更新':''}</p>`:'');}).join('');
 const trend=(data.history||[]).slice(-40),maximum=Math.max(100,...trend.map(item=>item.diskPercent||0));
 const points=trend.map((item,index)=>`${trend.length<2?0:index*500/(trend.length-1)},${80-(item.diskPercent||0)*70/maximum}`).join(' ');
 return `<section class="panel monitor-summary"><div><span class="monitor-kicker">PLATFORM HEALTH</span><h2>${esc(status)}</h2><p>无需打开后台也会自动采样。磁盘、主机内存和负载来自整台共享服务器，进程与请求指标仅属于 PaperKnow。</p></div><div><span class="badge ${!sampler.enabled?'':sampler.lastErrorAt||sampler.stale?'amber':a.length?'red':'green'}">${sampler.enabled?'每 '+esc(s.sampleIntervalSeconds)+' 秒采样':'自动采样已暂停'}</span><p>最近采样：${at(l?.sampledAt)}</p><button class="button" id="monitor-sample" ${sampler.enabled?'':'disabled'}>立即采样</button><span class="monitor-note">最多每 30 秒一次</span></div></section>
 ${sampler.lastErrorAt?'<div class="page-notice">最近一次采样未成功，以下可能是旧数据；请检查进程和数据库访问状态。</div>':''}
 <div class="monitor-metrics">${card('磁盘使用率',m?n(m.disk.usedPercent)+'%':'—',m?'剩余 '+bytes(m.disk.availableBytes)+' / 总容量 '+bytes(m.disk.totalBytes):'等待首轮采样',a.some(x=>['disk','disk-free'].includes(x.key))?'is-alert':'')}${card('本站进程内存',m?bytes(m.process.rssBytes):'—','进程 RSS；不含其他服务')}${card('共享主机内存',m?.host?.memoryUsedPercent===null?'暂无可用内存读数':m?n(m.host.memoryUsedPercent)+'%':'—','整台主机，不能归因于本站')}${card('主机每核心负载',n(m?.host?.loadPerCore),'1 分钟平均值 / CPU 核心数')}${card('排队 / 执行中',m?.jobs?n(m.jobs.queued)+' / '+n(m.jobs.running):'—','未更新异常 '+n(m?.jobs?.stale)+' 条')}${card('任务失败比例',m?.jobs?.failurePercent===null?'暂无完成样本':n(m?.jobs?.failurePercent)+'%','最近 24 小时完成与失败任务')}${card('接口 P95',m?.http?.p95Ms===null?'暂无请求':n(m?.http?.p95Ms)+' ms','最近 5 分钟 · '+n(m?.http?.count)+' 请求')}${card('接口 5xx 比例',m?.http?.errorPercent===null?'暂无请求':n(m?.http?.errorPercent)+'%','最近 5 分钟；不记录请求内容')}${card('待支付 / 过期未关单',m?.payments?n(m.payments.pending)+' / '+n(m.payments.expiredPending):'—','仅本站订单记录，不代表渠道对账')}${card('待结算预占',n(m?.reservations?.held),'超时 '+n(m?.reservations?.stale)+' 条 · '+n(m?.reservations?.credits)+' 积分')}${card('数据库 / WAL',m?bytes(m.database.bytes)+' / '+bytes(m.database.walBytes):'—','账号与交易等必要结构化记录')}${card('对象存储',m?.storage?.ok===true?'读写探测通过':m?.storage?.ok===false?'未通过探测':'待验证',m?.storage?.reason||'最近成功 '+at(m?.storage?.lastSuccessAt),m?.storage?.ok===false?'is-alert':'')}</div>
 <div class="monitor-columns"><section class="panel"><div class="panel-heading"><div><h2>当前告警</h2><p>仅在后台展示，恢复后自动结束；不会自动删除文件或发送消息。</p></div><span class="badge ${a.length?'amber':'green'}">${n(a.length)} 项</span></div><div class="monitor-alerts">${a.length?a.map(item=>`<article class="monitor-alert ${item.severity==='critical'?'critical':''}"><b>${esc(item.title)}</b><span>${item.severity==='critical'?'严重':'预警'} · 当前 ${esc(n(item.value))} ${esc(item.unit)} · 阈值 ${esc(n(item.threshold))}</span></article>`).join(''):'<p class="monitor-empty">当前样本未触发配置阈值。缺少数据或未完成探测不代表已经验证健康。</p>'}</div></section><section class="panel"><div class="panel-heading"><div><h2>容量与存储</h2><p>每 15 分钟读取可信容量汇总；缺少汇总时回退到本站目录的有界扫描。</p></div></div><div class="monitor-storage">${directories}${line('对象存储最近检查',at(m?.storage?.checkedAt))}${line('对象存储最近成功',at(m?.storage?.lastSuccessAt))}${line('文件存储补偿失败',n(m?.artifacts?.find(row=>row.status==='failed')?.count||0)+' 项')}${line('最多保留采样',n(data.retention?.maximumSamples)+' 条')}</div><p class="monitor-note monitor-pad">“至少”表示扫描不完整；“历史值”表示汇总超期。统计不是自动清理指令。</p></section></div>
 <section class="panel monitor-history"><div class="panel-heading"><div><h2>磁盘趋势与告警记录</h2><p>最近 ${n(data.history?.length||0)} 个采样；重启后保留有界历史。</p></div></div><div class="monitor-chart"><svg viewBox="0 0 500 90" role="img" aria-label="最近采样的磁盘使用率趋势"><path d="M0 80H500" stroke="#d9e5f6"/><polyline points="${points}" fill="none" stroke="#316cff" stroke-width="2"/></svg><span>磁盘使用率 · 最近 ${n(trend.length)} 个采样</span></div><div class="table-scroll monitor-events"><table class="data-table"><caption class="visually-hidden">告警变化记录</caption><thead><tr><th>时间</th><th>指标</th><th>变化</th></tr></thead><tbody>${(data.events||[]).map(event=>`<tr><td>${esc(at(event.at))}</td><td>${esc(metricNames[event.metric]||'运行指标')}</td><td><span class="badge ${event.status==='resolved'?'green':event.severity==='critical'?'red':'amber'}">${event.status==='resolved'?'已恢复':event.severity==='critical'?'严重告警':'触发预警'}</span></td></tr>`).join('')||'<tr><td colspan="3">暂无告警变化记录</td></tr>'}</tbody></table></div></section>
 <section class="panel monitor-settings"><div class="panel-heading"><div><h2>监控配置</h2><p>只允许调整采样周期与阈值，不接受服务器路径或外部通知地址。</p></div><span class="badge blue">配置版本 ${esc(s.version)}</span></div><form id="monitoring-form" class="settings-body"><label class="toggle-row"><span><b>启用自动运行监控</b><p>关闭后不再自动采样；已有历史保留。</p></span><input type="checkbox" name="enabled" ${s.enabled?'checked':''}></label><div class="monitor-field-grid">${settingsFields.map(([key,label,unit,min,max,step=1])=>`<div class="payment-field"><label for="monitor-${key}">${label}（${unit}）</label><input id="monitor-${key}" type="number" name="${key}" min="${min}" max="${max}" step="${step}" value="${esc(s[key])}" required></div>`).join('')}</div><p class="settings-note">失败比例与接口告警有最少样本要求。对象存储最多每 15 分钟实际探测一次。本站停机时无法自行发送告警，仍需云平台配置独立存活探测。</p><p class="form-error" role="alert" hidden></p><span class="settings-note" data-monitor-dirty hidden>有修改尚未保存</span><div class="settings-actions"><button class="button primary" type="submit">保存监控配置</button></div></form></section>`;
}
